"""Build the offline, source-paired two-ant review player."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent;D=ROOT/'integrated';s=json.loads((D/'shot.json').read_text());c=json.loads((D/'assembly-checks.json').read_text());e=escape
css='*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#171512;font:17px/1.5 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:20px}a{color:inherit}h1{font-size:clamp(32px,7vw,62px);line-height:1.05}nav,.tabs{display:flex;gap:12px 20px;flex-wrap:wrap}.meta{font-size:14px;color:#625b50}.badge{display:inline-block;background:#ef9f3a;padding:4px 9px;font-size:12px;font-weight:700}video{display:block;width:100%;max-height:65vh;background:#fffdf7}.tabs{margin:14px 0}button{font:inherit;border:1px solid #aaa18f;background:#fffdf7;color:#171512;border-radius:5px;padding:9px 14px;cursor:pointer}button[aria-pressed=true]{background:#171512;color:#fffdf7}.keys{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;border:1px solid #d5caba;background:#fffdf7;border-radius:6px;overflow:hidden;min-width:0}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pair img{width:100%;display:block}figcaption{padding:10px;font-size:13px}details{margin:22px 0}summary{cursor:pointer}footer{margin:28px 0;border-top:1px solid #d5caba;padding-top:16px;font-size:14px}.notice{border-left:4px solid #ef9f3a;background:#fffdf7;padding:12px 16px}@media(max-width:600px){.keys{grid-template-columns:1fr}main{padding:14px}button{font-size:15px}}'
script="const v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{})},{once:true});v.load()});"
cards=''.join(f'<figure><div class="pair"><img loading="lazy" src="source-{k:02d}.jpg" alt="Source at {s["frames"][f]["source_time"]:.3f}s"><img loading="lazy" src="key-{k:02d}.png" alt="Assembled two-ant key{k}"></div><figcaption>Key{k} · source{s["frames"][f]["source_time"]:.3f}s<br>{e(s["xsheet"][f]["note"])}</figcaption></figure>'for k,f in enumerate(s['keys'],1))
reviews=' · '.join(f'<a href="{p.name}">Independent review{i}</a>'for i,p in enumerate(sorted(D.glob('review-v*.json')),1));src=s['source'];tr=c['trace_fidelity'];badge=s.get('review_badge','ASSEMBLED REVIEW COPY')
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Two ants · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>{css}</style><body><main><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../moving-drawings.html">Moving drawings</a></nav><h1>Two ants at the rock edge.</h1><p class="meta">{s['frame_count']} frames ·{s['fps']}fps ·{len(s['keys'])} keys ·{s['duration']:.3f}s</p><p><span class="badge">{e(badge)}</span></p><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Drawing</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Together</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Footage</button></div><p class="notice">{e(s['review_note'])}</p><p class="meta">{e(s['assembly_summary'])}</p><h2>Eight observed configurations.</h2><p class="meta">Source at left, assembled drawing at right. Both ants keep the same original eleven-stroke construction.</p><section class="keys">{cards}</section><details><summary>Drawing, footage and checks</summary><p>Quick, Draw! ant key{s['design']['key_id']}, used twice. The three body sections, two antenna strokes and five leg strokes remain the original drawing. A sixth anatomical leg is not invented.</p><p>The original source plan described one ant. Source inspection rejected that assumption before drawing: both ants are visible throughout the retained interval0.200–2.200s. The opening cut is excluded.</p><p>Archive: <a href="{e(src['shot_page_url'])}">{e(src['source_title'])}</a> ({src['source_year']}). Archive reports public_domain; that report is retained without independent rights verification.</p><p>One rock plate follows background-only camera registration. Body centers and unequal leg/antenna endpoints are source-keyed estimates; material foot and antenna-contact identities remain unverified.</p><p>Trace minimum recall{tr['min_recall']:.4f}; pieces retained{tr['min_parts_kept']:.4f}; gate{'passes'if tr['pass']else'fails'}. Whole-shot mask fit is invalid: SAM alternates a single ant and both ants, and its last nominal sample is2.0s. Final0.2s has no independent cached mask. No final mask is reused beyond its sample.</p><p><a href="shot.json">Editable timeline</a> · <a href="source.json">Source record</a> · <a href="compatibility.json">Part compatibility</a> · <a href="correspondence.json">Correspondence</a> · <a href="camera.json">Camera</a> · <a href="assembly-checks.json">Checks</a> · <a href="traced.json">Trace</a> · <a href="sam/provenance.json">SAM provenance</a> · <a href="sam-audit.jpg">Mask inspection</a> · <a href="design.png">Original doodle</a> · <a href="source-contact-sheet.jpg">Source contact sheet</a> ·{reviews}</p><p>Classifier and independent normal-speed playback approval remain unrun. No training ran. This is not an accepted training pair.</p></details><footer>Quick, Draw! contributors / Google Creative Lab, CC BY4.0. <a href="cartoon.mp4" download>Download drawing</a> · <a href="comparison.mp4" download>Download comparison</a></footer></main><script>{script}</script></html>'''
(D/'index.html').write_text(html);print(D/'index.html')
